function qty(string $x):?int{$x=trim(str_replace(["\xc2\xa0",' '],'',$x));if($x==='')return null;$x=str_replace(',','.',$x);if(!preg_match('/^-?\d+(?:\.\d+)?$/u',$x))return null;return max(0,(int)floor((float)$x));}
